"""Rule-based (NON-AI) fallbacks.

These run only when a user explicitly asks for them after the Claude API is
unavailable (or for the code-quality checks, which are deterministic). Every
result produced here is stored with source='rule_based' and labelled in the UI
as a non-AI assessment.
"""
from __future__ import annotations

import ast
import re

FALLBACK_NOTICE = (
    "Rule-based estimate - NOT an AI assessment. Generated by keyword/static rules "
    "because the AI API was unavailable or not used. Teacher review recommended."
)

_WORD = re.compile(r"[a-z0-9]+")


def _stem(word: str) -> str:
    for suffix in ("ing", "ness", "ity", "ies", "es", "ed", "ly", "s"):
        if len(word) > len(suffix) + 3 and word.endswith(suffix):
            return word[: -len(suffix)]
    return word


def _words(text: str) -> set:
    return {_stem(w) for w in _WORD.findall(text.lower())}


def viva_keyword_estimate(question, answer: str) -> dict:
    """Score = share of the question's key concepts that appear in the answer."""
    concepts = [c.strip() for c in (question["key_concepts"] or "").split(",") if c.strip()]
    max_score = float(question["max_score"])
    if not concepts:
        concepts = [w for w in _WORD.findall(question["reference_answer"].lower()) if len(w) > 6][:8]
    answer_words = _words(answer)
    found, missing = [], []
    for concept in concepts:
        parts = _words(concept)
        if parts and parts <= answer_words:
            found.append(concept)
        else:
            missing.append(concept)
    fraction = len(found) / len(concepts) if concepts else 0.0
    if len(answer.split()) < 8:
        fraction *= 0.5  # very short answers cannot fully explain a concept
    score = round(max_score * fraction * 2) / 2
    score = max(0.0, min(max_score, score))
    return {
        "score": score,
        "max_score": max_score,
        "correct_concepts": found,
        "missing_concepts": missing,
        "strengths": [f"Mentions {c}" for c in found[:3]],
        "feedback": (
            f"{FALLBACK_NOTICE} The answer mentions {len(found)} of {len(concepts)} key "
            "concepts. Keyword matching cannot judge whether they are explained correctly."
        ),
        "suggestion": (
            "Explain: " + ", ".join(missing) + "." if missing
            else "Retry the AI assessment for detailed feedback on correctness."
        ),
    }


def code_quality_rules(code: str) -> dict:
    """Deterministic static checks used when the AI review is unavailable."""
    findings = []
    lines = code.splitlines()

    def add(category, severity, line, title, explanation, recommendation):
        findings.append({
            "category": category, "severity": severity, "line": line, "title": title,
            "explanation": explanation, "recommendation": recommendation,
        })

    for i, line in enumerate(lines, 1):
        if len(line) > 100:
            add("readability", "low", i, "Long line",
                f"Line is {len(line)} characters long.", "Keep lines under about 100 characters.")
        if "\t" in line[: len(line) - len(line.lstrip())]:
            add("readability", "low", i, "Tab indentation",
                "Tabs are used for indentation.", "Use 4 spaces per indent level (PEP 8).")
    try:
        tree = ast.parse(code)
    except SyntaxError as exc:
        add("logic", "high", exc.lineno, "Syntax error", str(exc.msg), "Fix the syntax error first.")
        tree = None
    if tree is not None:
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if ast.get_docstring(node) is None:
                    add("documentation", "low", node.lineno, f"No docstring for {node.name}()",
                        "Functions without docstrings are harder to understand.",
                        "Add a one-line docstring describing inputs and output.")
                if not re.fullmatch(r"[a-z_][a-z0-9_]*", node.name):
                    add("naming", "low", node.lineno, f"Function name '{node.name}'",
                        "Python functions normally use snake_case.", "Rename using snake_case.")
                length = (getattr(node, "end_lineno", node.lineno) or node.lineno) - node.lineno
                if length > 40:
                    add("organization", "medium", node.lineno, f"{node.name}() is long",
                        f"The function spans about {length} lines.",
                        "Split it into smaller helper functions.")
            elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                if len(node.id) == 1 and node.id not in {"i", "j", "k", "n", "x", "y", "_"}:
                    add("naming", "info", node.lineno, f"Single-letter name '{node.id}'",
                        "Short names can hide meaning.", "Use a descriptive variable name.")
            elif isinstance(node, ast.ExceptHandler) and node.type is None:
                add("logic", "medium", node.lineno, "Bare except",
                    "A bare `except:` hides unexpected errors.", "Catch specific exceptions.")
    comment_lines = sum(1 for l in lines if l.strip().startswith("#"))
    if len(lines) > 15 and comment_lines == 0:
        add("documentation", "info", None, "No comments",
            "The program has no explanatory comments.", "Comment non-obvious steps.")
    # de-duplicate repeated single-letter warnings
    seen, unique = set(), []
    for f in findings:
        key = (f["title"], f["category"])
        if key not in seen:
            seen.add(key)
            unique.append(f)
    return {
        "summary": f"{FALLBACK_NOTICE} {len(unique)} rule-based finding(s).",
        "findings": unique[:25],
    }


def performance_rules(stats: dict) -> dict:
    """Threshold-based summary of the statistics (no AI)."""
    topics = stats.get("topics", [])
    strong = [t["topic"] for t in topics if t["percent"] is not None and t["percent"] >= 75]
    weak = [t["topic"] for t in topics if t["percent"] is not None and t["percent"] < 50]
    middle = [t["topic"] for t in topics if t["percent"] is not None and 50 <= t["percent"] < 75]
    overall = stats.get("overall_percent")
    overview = FALLBACK_NOTICE + " "
    if overall is None:
        overview += "No assessed work is available yet."
    else:
        overview += (
            f"Overall score across {stats.get('assessment_count', 0)} assessment(s): {overall:.0f}%."
        )
    suggestions = [f"Re-read the lab notes for {t} and re-attempt its viva questions." for t in weak]
    suggestions += [f"Practise one more problem on {t}." for t in middle]
    if not suggestions:
        suggestions = ["Keep attempting new viva questions and assignments to maintain progress."]
    return {
        "overview": overview,
        "strong_topics": strong,
        "weak_topics": weak,
        "revision_topics": weak + middle,
        "study_suggestions": suggestions[:8],
    }
